local StarChartRackMaker = {}
local PRODUCTS = {
    iron_starchartrack = { name = "Železni stojalo za zvezdne karte", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni stojalo za zvezdne karte za zvezdarje." },
    bronze_starchartrack = { name = "Bronast stojalo za zvezdne karte", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast stojalo za zvezdne karte za zvezdarje." },
    silver_starchartrack = { name = "Srebrn stojalo za zvezdne karte", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn stojalo za zvezdne karte za zvezdarje." },
    gilded_starchartrack = { name = "Pozlačen stojalo za zvezdne karte", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen stojalo za zvezdne karte za zvezdarje." },
    jewel_set_starchartrack = { name = "Draguljast stojalo za zvezdne karte", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast stojalo za zvezdne karte za zvezdarje." },
    royal_sovereign_starchartrack = { name = "Kraljevski suveren stojalo za zvezdne karte", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren stojalo za zvezdne karte z biseri za krono." },
}
local BUILDINGS = {
    starchartrack_workshop = { name = "Starchartrack delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    starchartrack_house = { name = "Starchartrack hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_starchartrack_atelier = { name = "Mojstrski starchartrack atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_starchartrack_palace = { name = "Suverena starchartrack palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
StarChartRackMaker.ironStock = 12; StarChartRackMaker.bronzeStock = 10; StarChartRackMaker.woodStock = 18; StarChartRackMaker.leatherStock = 10; StarChartRackMaker.silverStock = 8; StarChartRackMaker.goldStock = 6; StarChartRackMaker.jewelStock = 4; StarChartRackMaker.pearlStock = 4
StarChartRackMaker.productStock = {}; StarChartRackMaker.buildings = {}; StarChartRackMaker.maker = nil; StarChartRackMaker.activeMaking = {}; StarChartRackMaker.totalProducts = 0; StarChartRackMaker.dayTimer = 0
function StarChartRackMaker.init() StarChartRackMaker.ironStock=12; StarChartRackMaker.bronzeStock=10; StarChartRackMaker.woodStock=18; StarChartRackMaker.leatherStock=10; StarChartRackMaker.silverStock=8; StarChartRackMaker.goldStock=6; StarChartRackMaker.jewelStock=4; StarChartRackMaker.pearlStock=4; StarChartRackMaker.productStock={}; StarChartRackMaker.buildings={}; StarChartRackMaker.maker=nil; StarChartRackMaker.activeMaking={}; StarChartRackMaker.totalProducts=0; StarChartRackMaker.dayTimer=0; print("[StarChartRackMaker] Royal Star Chart Rack Maker System initialized (6 products, 4 buildings)") end
function StarChartRackMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StarChartRackMaker.maker={name=n or ("Zvezdar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zvezdar najet: %s (spretnost: %d)",StarChartRackMaker.maker.name,s),"success") end; return true end
function StarChartRackMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StarChartRackMaker.build(id) local ok,e=StarChartRackMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StarChartRackMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StarChartRackMaker.getQualityBonus() local b=0; for _,bd in ipairs(StarChartRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StarChartRackMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and StarChartRackMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and StarChartRackMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and StarChartRackMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and StarChartRackMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and StarChartRackMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and StarChartRackMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and StarChartRackMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and StarChartRackMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #StarChartRackMaker.buildings==0 then return false,"Potrebna zvezdna delavnica" end; if not StarChartRackMaker.maker then return false,"Potreben zvezdar" end; return true end
function StarChartRackMaker.make(pt,qty) qty=qty or 1; local ok,e=StarChartRackMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then StarChartRackMaker.ironStock=StarChartRackMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then StarChartRackMaker.bronzeStock=StarChartRackMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then StarChartRackMaker.woodStock=StarChartRackMaker.woodStock-d.woodCost*qty end; if d.leatherCost then StarChartRackMaker.leatherStock=StarChartRackMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then StarChartRackMaker.silverStock=StarChartRackMaker.silverStock-d.silverCost*qty end; if d.goldCost then StarChartRackMaker.goldStock=StarChartRackMaker.goldStock-d.goldCost*qty end; if d.jewelCost then StarChartRackMaker.jewelStock=StarChartRackMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then StarChartRackMaker.pearlStock=StarChartRackMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if StarChartRackMaker.maker then t=math.max(1,t-math.floor(StarChartRackMaker.maker.skill/13)) end; table.insert(StarChartRackMaker.activeMaking,{id="starchartrack_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StarChartRackMaker.completeMaking(m) local q=1.0+(StarChartRackMaker.getQualityBonus()/100); if StarChartRackMaker.maker then q=q+(StarChartRackMaker.maker.skill/140) end; q=math.min(2.5,q); StarChartRackMaker.productStock[m.productType]=(StarChartRackMaker.productStock[m.productType] or 0)+m.quantity; StarChartRackMaker.totalProducts=StarChartRackMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StarChartRackMaker.maker then StarChartRackMaker.maker.itemsMade=StarChartRackMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then StarChartRackMaker.maker.skill=math.min(100,StarChartRackMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stojalo izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"starchartrack.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function StarChartRackMaker.update(dt) if not _G.state then return end; StarChartRackMaker.dayTimer=StarChartRackMaker.dayTimer+dt; if StarChartRackMaker.dayTimer>=30 then StarChartRackMaker.dayTimer=0; for i=#StarChartRackMaker.activeMaking,1,-1 do local m=StarChartRackMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StarChartRackMaker.completeMaking(m); table.remove(StarChartRackMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StarChartRackMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StarChartRackMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StarChartRackMaker.getStats() return {ironStock=StarChartRackMaker.ironStock,bronzeStock=StarChartRackMaker.bronzeStock,woodStock=StarChartRackMaker.woodStock,leatherStock=StarChartRackMaker.leatherStock,silverStock=StarChartRackMaker.silverStock,goldStock=StarChartRackMaker.goldStock,jewelStock=StarChartRackMaker.jewelStock,pearlStock=StarChartRackMaker.pearlStock,productStock=StarChartRackMaker.productStock,numBuildings=#StarChartRackMaker.buildings,hasMaker=StarChartRackMaker.maker~=nil,makerName=StarChartRackMaker.maker and StarChartRackMaker.maker.name or "—",makerSkill=StarChartRackMaker.maker and StarChartRackMaker.maker.skill or 0,activeMaking=#StarChartRackMaker.activeMaking,totalProducts=StarChartRackMaker.totalProducts} end
return StarChartRackMaker
